  "overlap_is_channel": false,
  "attribution": "removal_lift",
  "explanation": {
    "overlap_status": "Overlap is NOT a media channel. It is a reconciliation term that appears only under log-link removal_lift attribution. It reconciles the decomposition when multiple channels interact multiplicatively.",
    "attribution_convention": "removal_lift - This is a counterfactual attribution method that measures each channel's contribution by removing it and observing the impact on KPI. Under log-link (multiplicative) models, the Overlap term captures the interaction effects between channels that would otherwise be double-counted.",
